import{af as a,z as s,J as i,ab as t}from"./chunks/framework.plagcClB.js";const g=JSON.parse('{"title":"Lightbug docs","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),n={name:"README.md"};function o(l,e,r,d,p,h){return s(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794420474000"},[...e[0]||(e[0]=[t(`<h1 id="lightbug-docs" tabindex="-1">Lightbug docs <a class="header-anchor" href="#lightbug-docs" aria-label="Permalink to &quot;Lightbug docs&quot;">​</a></h1><p>Code powering <a href="https://docs.lightbug.io" target="_blank" rel="noreferrer">https://docs.lightbug.io</a> making use of vitepress</p><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><p>Install dependencies</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>Run the development server</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Or build and serve the static site</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><h2 id="deployments" tabindex="-1">Deployments <a class="header-anchor" href="#deployments" aria-label="Permalink to &quot;Deployments&quot;">​</a></h2><p>Merges to the <code>main</code> branch will auto deploy onto <a href="https://docs-next.lightbug.io" target="_blank" rel="noreferrer">https://docs-next.lightbug.io</a></p><p>The <code>production</code> branch will deploy to the main site at <a href="https://docs.lightbug.io" target="_blank" rel="noreferrer">https://docs.lightbug.io</a></p><h3 id="reproducing-ci-builds-locally" tabindex="-1">Reproducing CI builds locally <a class="header-anchor" href="#reproducing-ci-builds-locally" aria-label="Permalink to &quot;Reproducing CI builds locally&quot;">​</a></h3><p>The site build uses an environment variable <code>DEPLOYMENT_NAME</code> to alter some config (for example <code>sitemap</code> and <code>editLink</code>). CI sets this during the build step. To reproduce CI builds locally you can use the included npm scripts:</p><ul><li><code>npm run build:next</code> — sets <code>DEPLOYMENT_NAME=Next</code> (matches <code>main</code> branch/next site)</li><li><code>npm run build:production</code> — sets <code>DEPLOYMENT_NAME=Production</code> (matches <code>production</code> branch/main site)</li></ul><p>Both scripts use <code>cross-env</code> so they work cross-platform.</p><p>PR preview workflows and administrator setup: <a href="https://github.com/lightbug-io/docs/blob/main/.github/preview/README.md" target="_blank" rel="noreferrer">.github/preview</a>.</p><h2 id="protocol-yaml-authoring-and-export" tabindex="-1">Protocol YAML authoring and export <a class="header-anchor" href="#protocol-yaml-authoring-and-export" aria-label="Permalink to &quot;Protocol YAML authoring and export&quot;">​</a></h2><p><code>public/files/protocol-v3.yaml</code> is the canonical source. It uses native YAML anchors (<code>&amp;name</code>), aliases (<code>*name</code>) and merge keys (<code>&lt;&lt;: *name</code>), parsed by the same <code>js-yaml</code> dependency used by the docs. There is no separate template engine. Consumers without merge-key support can use the expanded export below.</p><ul><li>Definitions used only within one message are anchored at their first use in that message. Use message-specific anchor names: anchors have document scope, not message scope, and must appear before their aliases.</li><li>Only header maps shared across messages live in the top-level <code>templates.headers</code> registry: <code>optionalOkReply</code>, <code>correlatedOkAck</code>, and <code>optionalCorrelationAck</code>. An anchor has no effect unless explicitly aliased or merged into an actual message definition.</li><li>A YAML merge is shallow. An explicit key replaces that entire merged value; replacing a header entry does not inherit the entry&#39;s other properties. Anchor smaller maps when individual nested values need to be reused.</li></ul><h3 id="navigate-shared-definitions" tabindex="-1">Navigate shared definitions <a class="header-anchor" href="#navigate-shared-definitions" aria-label="Permalink to &quot;Navigate shared definitions&quot;">​</a></h3><p>In VS Code with <a href="https://github.com/redhat-developer/vscode-yaml" target="_blank" rel="noreferrer">Red Hat YAML</a>, put the caret on an alias (<code>*name</code>) and run <strong>Go to Definition</strong> from the context menu. The extension&#39;s language server <a href="https://github.com/redhat-developer/yaml-language-server/blob/main/src/languageservice/services/yamlDefinition.ts" target="_blank" rel="noreferrer">resolves aliases to their anchors</a>. This follows the explicit alias, not an inherited field name or arbitrary string.</p><p><a href="https://www.jetbrains.com/help/idea/yaml.html" target="_blank" rel="noreferrer">IntelliJ IDEA&#39;s YAML support</a> documents alias-to-anchor navigation, anchor usages, and anchor/alias rename. Use <strong>Go to Declaration or Usages</strong>; the shortcut depends on your key bindings. These are editor features, not something the docs site adds. If your editor or extension version lacks them, search for <code>&amp;name</code> in the canonical file. The expanded download below is useful for inspecting all values without jumping.</p><h3 id="export-expanded-yaml" tabindex="-1">Export expanded YAML <a class="header-anchor" href="#export-expanded-yaml" aria-label="Permalink to &quot;Export expanded YAML&quot;">​</a></h3><p>The protocol overview offers <strong>Download expanded YAML</strong> at <code>files/protocol-v3-expanded.yaml</code>, including on PR previews. The build creates it from the canonical source; the development server generates it on each request. Do not commit or edit a second generated specification.</p><p>To inspect or save the same output locally after installing dependencies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --silent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export:protocol</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --silent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export:protocol</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/protocol-v3-expanded.yaml</span></span></code></pre></div><p>The export resolves aliases and merge keys using the <code>yaml</code> library&#39;s typed maps, keeping numeric keys as integers and deliberately quoted keys as strings for SDK generator compatibility. It emits no anchors and removes only the top-level authoring-only <code>templates</code> registry. All other parsed data is preserved, including sentinels and version overrides. It does not invent runtime defaults or flatten message-version description inheritance. Comments and source formatting are not retained. Edit the canonical source and re-export.</p><h2 id="protocol-sentinel-values" tabindex="-1">Protocol sentinel values <a class="header-anchor" href="#protocol-sentinel-values" aria-label="Permalink to &quot;Protocol sentinel values&quot;">​</a></h2><p>Numeric field definitions in <code>public/files/protocol-v3.yaml</code> can declare raw sentinel values separately from ordinary enum <code>values</code>. For example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">int16</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">conversion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">unit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">C</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">sentinels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -32768</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">unavailable</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Unavailable</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">No temperature was available at the resistance measurement.</span></span></code></pre></div><p>Keys are decoded raw numeric values, before conversion. Each entry has a stable <code>id</code>, a display <code>name</code>, and an optional <code>description</code>. A matching value displays <code>Unavailable (raw -32768)</code> without conversion or physical units. Other values retain normal parsing and formatting. The wire type and bytes are unchanged; an omitted field remains different from a present field carrying a sentinel. Only fields that explicitly declare a sentinel use this behavior. It applies to scalar numeric fields, not strings or individual elements of arrays.</p><p>The annotated message parser and captured-example summaries share the same lookup. Both structured and legacy field references list the declared sentinel values from the spec.</p><p>The upstream YAML exporter lives in <code>lightbug-io/gingin</code>, outside this repository. Its typed <code>MessageData</code> schema needs a corresponding <code>sentinels</code> property and round-trip coverage before regeneration can preserve this metadata. Until that follow-up is made, do not overwrite the docs spec with an upstream export without retaining these declarations. The docs site itself reads the YAML directly.</p>`,34)])])}const u=a(n,[["render",o]]);export{g as __pageData,u as default};
